def prime_table(N):

    is_prime = np.zeros(N, np.int64)

    is_prime[2:3] = 1

    is_prime[3::2] = 1

    for p in range(3, N, 2):

        if p * p >= N:

            break

        if is_prime[p]:

            is_prime[p * p::p + p] = 0

    return is_prime, np.where(is_prime)[0]



def main(N, primes):

    div = np.ones(N + 1, dtype=np.int64)

    for p in primes:

        for i in range(N // p + 1):

            div[p * i] += div[i]

    div *= np.arange(N + 1)

